import random
from typing import List

# Data type: arbitrary binary data
# Generate inputs suitable for Utils crypto and Packet stubs.
# Keep total size <= 4096 bytes. No I/O.

MAX_TOTAL = 4096

ASCII_DICT = (
    b"",  # empty
    b"a",
    b"0",
    b"The quick brown fox jumps over the lazy dog",
    b"Lorem ipsum dolor sit amet, consectetur adipiscing elit",
    b"\x00" * 8,  # NULs
    b"\xff" * 16,
    b"1234567890",
    b"A" * 128,
    b"B" * 255,
)


def _rand_bytes(r: random.Random, n: int) -> bytes:
    return bytes(r.getrandbits(8) for _ in range(n))


def _pattern_bytes(r: random.Random, n: int) -> bytes:
    # Compose from small motifs to create realistic structure
    motifs = [
        b"\x00", b"\xff", b"\x01", b"\x7f", b"\x80",
        b"AB", b"\x12\x34", b"\xaa\x55", b"\x00\xff",
    ]
    out = bytearray()
    while len(out) < n:
        m = r.choice(motifs)
        reps = 1 + r.randrange(1, 8)
        out.extend(m * reps)
    del out[n:]
    return bytes(out)


def _block_aligned_lengths(r: random.Random) -> List[int]:
    # Favor AES block-aligned lengths but include edge cases
    lens = {0, 1, 15, 16, 17, 31, 32, 47, 48, 63, 64, 79, 80, 95, 96, 127, 128, 255, 256, 511, 512}
    # Add a few random up to 512 as used by stubs
    for _ in range(6):
        lens.add(r.randrange(0, 513))
    return sorted(lens)


def _hex_alphabet() -> bytes:
    return b"0123456789abcdef"


def _make_hex_string(r: random.Random, nbytes: int) -> bytes:
    # Produce exactly 2*nbytes hex chars
    alpha = _hex_alphabet()
    return bytes(alpha[r.randrange(16)] for _ in range(nbytes * 2))


def _dedupe_join(parts: List[bytes], limit: int) -> bytes:
    # Concatenate parts while ensuring total size limit
    out = bytearray()
    for p in parts:
        if not p:
            continue
        want = min(len(p), max(0, limit - len(out)))
        if want <= 0:
            break
        out.extend(p[:want])
    return bytes(out)


def generate(seed: int) -> bytes:
    r = random.Random(seed)

    parts: List[bytes] = []

    # 1) Keys for AES-128 (16 bytes), multiple variants
    key_base = _rand_bytes(r, 16)
    parts.append(key_base)
    parts.append(bytes([i & 0xFF for i in range(16)]))  # 00..0f
    parts.append(b"\x00" * 16)
    parts.append(b"\xff" * 16)

    # 2) Plaintexts and fragments for sha256/encrypt
    for L in _block_aligned_lengths(r):
        choice = r.randrange(4)
        if choice == 0:
            buf = _rand_bytes(r, L)
        elif choice == 1:
            buf = _pattern_bytes(r, L)
        elif choice == 2:
            base = r.choice(ASCII_DICT)
            if len(base) == 0:
                buf = b""
            else:
                reps = (L + len(base) - 1) // max(1, len(base))
                buf = (base * reps)[:L]
        else:
            buf = bytes((i % 256) for i in range(L))
        parts.append(buf)

    # 3) Two-fragment SHA-256 cases
    for f1_len in (0, 1, 16, 31, 32, 255, 256):
        for f2_len in (0, 1, 16, 31, 32, 255, 256):
            parts.append(_rand_bytes(r, f1_len))
            parts.append(_pattern_bytes(r, f2_len))

    # 4) Hex strings for fromHex
    for nbytes in (0, 16, 32):
        parts.append(_make_hex_string(r, nbytes))

    # 5) Packet payloads and paths typical sizes
    for L in (0, 7, 31, 32, 33, 63, 64, 65, 127, 128):
        parts.append(_rand_bytes(r, L))

    # 6) Include some delimiters for parseTextParts
    delimited = []
    for _ in range(4):
        fields = r.randrange(1, 8)
        elems = []
        for i in range(fields):
            el_len = r.randrange(0, 16)
            if el_len == 0:
                elems.append(b"")
            else:
                chunk = bytearray()
                for _j in range(el_len):
                    c = r.choice(b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789")
                    chunk.append(c)
                elems.append(bytes(chunk))
        sep = r.choice([b",", b";", b"|"])
        delimited.append(sep.join(elems))
    parts.extend(delimited)

    # 7) Small buffers and transport codes (ensure bytes in 0..255)
    for _ in range(6):
        # produce a single unsigned byte; avoid negative conversion
        val = r.randrange(0, 256)
        parts.append(bytes([val]))
        tc0 = r.randrange(0, 65536).to_bytes(2, "little")
        tc1 = r.randrange(0, 65536).to_bytes(2, "little")
        parts.append(tc0 + tc1)

    # 8) Mix in some repeated key/plain combos to encourage valid decrypt paths
    for _ in range(4):
        pt_len = r.randrange(0, 513)
        pt = _rand_bytes(r, pt_len)
        parts.append(pt)
        parts.append(key_base)

    # Shuffle parts to diversify ordering
    r.shuffle(parts)

    return _dedupe_join(parts, MAX_TOTAL)
